scripts.resume2-select-375-bc.py:
"""Continue the interrupted 51-repository B resume (#375) without re-running finished pytest checks.

Same `round2_tasks.py select` and the same constants as the first resume (B target 24, C and development targets
0). A candidate whose pytest outputs the interrupted run already wrote (raw-v4-resume: baseline, and parent +
reference when the baseline passed) is decided from those outputs instead of running pytest again; every other
candidate is validated as usual and its outputs go to the new raw directory. Replayed candidates are listed in the
output under "replayed".

    python resume2-select-375-bc.py OLD_RAW_DIR <select arguments...>
"""
import re
import sys
from pathlib import Path

sys.path.insert(0, "scripts/eval")
import round2_tasks as R

R.B_TAKE, R.C_TAKE, R.B_DEV_TAKE, R.C_DEV_TAKE = 24, 0, 0, 0
OLDS = [Path(p) for p in sys.argv[1].split(",")]  # earlier raw directories, searched in order
REPLAYED = []


def _old_files(stem: str) -> dict:
    """The earlier outputs of one candidate from the first directory that has its baseline."""
    for d in OLDS:
        if (d / f"{stem}-baseline.txt").is_file():
            return {k: d / f"{stem}-{k}.txt" for k in ("baseline", "parent", "reference")}
    return {k: OLDS[0] / f"{stem}-{k}.txt" for k in ("baseline", "parent", "reference")}


def _rc(text: str):
    """The pytest exit code an output stands for: None for a timeout, 0 for passed tests without failures or
    errors, 5 for no tests, 1 for failures, 2 for errors only, 1 for anything else (a crash before the summary)."""
    lines = text.strip().splitlines()
    last = lines[-1] if lines else ""
    if last.endswith("timeout"):
        return None, last
    if re.search(r"\d+ failed", last):
        return 1, last
    if re.search(r"\d+ errors?\b", last) or "Interrupted" in text:
        return 2, last
    if re.search(r"\d+ passed", last):
        return 0, last
    if "no tests ran" in last:
        return 5, last
    return 1, last


def replay_or_validate(cache, python, task, raw_dir):
    stem = task["commit"]
    files = _old_files(stem)
    if files["baseline"].is_file():
        b_rc, b_sum = _rc(files["baseline"].read_text(encoding="utf-8", errors="replace"))
        if b_rc != 0:
            REPLAYED.append(task["id"])
            return {"baseline": {"rc": b_rc, "summary": b_sum, "replayed": True},
                    "parent": {"rc": None, "summary": "not run: original parent baseline failed"},
                    "reference": {"rc": None, "summary": "not run: original parent baseline failed"},
                    "valid": False}
        if files["parent"].is_file() and files["reference"].is_file():
            p_rc, p_sum = _rc(files["parent"].read_text(encoding="utf-8", errors="replace"))
            r_rc, r_sum = _rc(files["reference"].read_text(encoding="utf-8", errors="replace"))
            REPLAYED.append(task["id"])
            return {"baseline": {"rc": 0, "summary": b_sum, "replayed": True},
                    "parent": {"rc": p_rc, "summary": p_sum, "replayed": True},
                    "reference": {"rc": r_rc, "summary": r_sum, "replayed": True},
                    "valid": p_rc in (1, 2) and r_rc == 0}
    return R._validate(cache, python, task, raw_dir)


_select = R.select_upstream


def select_with_replay(*args, **kwargs):
    kwargs["validator"] = replay_or_validate
    out = _select(*args, **kwargs)
    out["replayed"] = list(REPLAYED)
    return out


R.select_upstream = select_with_replay
raise SystemExit(R.main(["select", *sys.argv[2:]]))
